const onceTag = ab => {
  const t = ab.text || '', army = /\bone (model|unit) from your army with this ability\b/i.test(t);
  // as BSData prints it; ", per army" as below when the tag does not say per what ("Once per battle round": Direct the Slaughter)
  if(/^(once|twice) per /i.test(ab.tag || '')){ const tg = ab.tag.replace(/ · .*$/, ''); return tg + (army && !/\bper (army|unit)\b/i.test(tg) ? ', per army' : ''); }
  // an enhancement's text starts with its restriction ("**TECH-PRIEST** model only. Once per battle round, …")
  const t1 = t.replace(/^\*\*[^*]+\*\* model only( \([^)]*\))?\. /i, '');
  for(const src of [ab.tag || '', (/\((once per [^)]+)\)/i.exec(t) || [])[1] || '', (/^once per [^,.]+(, per (army|unit))?/i.exec(t1) || [])[0] || '']){
    const m = /once per (battle round|battle|phase|turn)(, per (army|unit))?/i.exec(src);
    if(m) return m[0].replace(/^o/, 'O') + (!m[2] && army ? ', per army' : '');
  }
  return '';
};
